bash -c 'echo "===== LOAD ====="; uptime; echo "===== MEMORY ====="; free -h; echo "===== LISTEN ====="; ss -lntp; echo "===== NGINX ====="; systemctl status nginx --no-pager -l | head -20; echo "===== XRAY ====="; systemctl status x-ui --no-pager -l | head -20; echo "===== ERRORS ====="; tail -30 /var/log/nginx/error.log 2>/dev/null'
